// Local shim for "@opencode/plugin".
//
// OpenCode resolves a path-based plugin's imports through normal node_modules
// lookup, and a path plugin has no npm install step, so the package would be
// missing. Upstream dist/promise/plugin.js is:
//
//     export function define(plugin) { return plugin; }
//
// and the root entry merely re-exports it as the `Plugin` namespace. This file
// reproduces exactly that surface, so `import { Plugin } from "@opencode/plugin"`
// behaves the same as the published package for a plugin that only calls
// Plugin.define().
function define(plugin) {
  return plugin;
}

export const Plugin = { define };
export { define };
export default { Plugin };
